PRAGMA foreign_keys=ON;
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE groups(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE subjects(id TEXT PRIMARY KEY,name TEXT NOT NULL,short TEXT NOT NULL,color TEXT NOT NULL,path TEXT NOT NULL DEFAULT 'common');
CREATE TABLE offerings(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES subjects(id),group_id TEXT NOT NULL REFERENCES groups(id),teacher TEXT NOT NULL,variant TEXT NOT NULL DEFAULT '',path TEXT NOT NULL DEFAULT 'common');
CREATE TABLE slots(id TEXT PRIMARY KEY,offering_id TEXT NOT NULL REFERENCES offerings(id) ON DELETE CASCADE,day INTEGER NOT NULL CHECK(day BETWEEN 0 AND 6),start TEXT NOT NULL,end TEXT NOT NULL,room TEXT NOT NULL DEFAULT '');
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student' CHECK(role IN('student','delegate','admin')),group_id TEXT REFERENCES groups(id),path TEXT NOT NULL DEFAULT 'science',configured INTEGER NOT NULL DEFAULT 0,balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),disabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TABLE sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE invitations(hash TEXT PRIMARY KEY,label TEXT NOT NULL,group_id TEXT REFERENCES groups(id),expires INTEGER NOT NULL,max_uses INTEGER NOT NULL DEFAULT 1,uses INTEGER NOT NULL DEFAULT 0 CHECK(uses<=max_uses));
CREATE TABLE recovery_tokens(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE enrollments(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,offering_id TEXT NOT NULL REFERENCES offerings(id),PRIMARY KEY(user_id,offering_id));
CREATE TABLE events(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('exam','deadline','reminder','event')),date TEXT NOT NULL,start TEXT,end TEXT,subject_id TEXT REFERENCES subjects(id),offering_id TEXT REFERENCES offerings(id),group_id TEXT REFERENCES groups(id),room TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',visibility TEXT NOT NULL CHECK(visibility IN('private','shared')),source_key TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TABLE notes(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),subject_id TEXT NOT NULL REFERENCES subjects(id),title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',summary TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL DEFAULT 0 CHECK(price>=0 AND price<=10000),status TEXT NOT NULL DEFAULT 'published' CHECK(status IN('published','draft','archived')),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TABLE files(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,object_key TEXT NOT NULL UNIQUE,note_id TEXT REFERENCES notes(id),plus_id TEXT,proposal_id TEXT,preview INTEGER NOT NULL DEFAULT 0,position INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TABLE pluses(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,date TEXT NOT NULL,start TEXT,end TEXT,place TEXT NOT NULL,conditions TEXT NOT NULL DEFAULT '',url TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TABLE plus_subjects(plus_id TEXT NOT NULL REFERENCES pluses(id) ON DELETE CASCADE,subject_id TEXT NOT NULL REFERENCES subjects(id),bonus TEXT NOT NULL,PRIMARY KEY(plus_id,subject_id));
CREATE TABLE likes(user_id TEXT NOT NULL REFERENCES users(id),type TEXT NOT NULL CHECK(type IN('note','plus')),target_id TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(user_id,type,target_id));
CREATE TABLE saves(user_id TEXT NOT NULL REFERENCES users(id),type TEXT NOT NULL CHECK(type IN('note','plus')),target_id TEXT NOT NULL,PRIMARY KEY(user_id,type,target_id));
CREATE TABLE consultations(user_id TEXT NOT NULL REFERENCES users(id),note_id TEXT NOT NULL REFERENCES notes(id),day TEXT NOT NULL,PRIMARY KEY(user_id,note_id));
CREATE TABLE ledger(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount!=0),reason TEXT NOT NULL,ref TEXT NOT NULL UNIQUE,day TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TRIGGER ledger_balance AFTER INSERT ON ledger BEGIN UPDATE users SET balance=balance+NEW.amount WHERE id=NEW.user_id; END;
CREATE TABLE contribution_rewards(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),day TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TRIGGER contribution_credit AFTER INSERT ON contribution_rewards WHEN(SELECT COUNT(*) FROM contribution_rewards WHERE author_id=NEW.author_id AND day=NEW.day)<=30 BEGIN INSERT INTO ledger(id,user_id,amount,reason,ref,day) VALUES(NEW.id,NEW.author_id,1,NEW.reason,NEW.id,NEW.day); END;
CREATE TABLE daily_claims(user_id TEXT NOT NULL REFERENCES users(id),day TEXT NOT NULL,PRIMARY KEY(user_id,day));
CREATE TRIGGER daily_credit AFTER INSERT ON daily_claims BEGIN INSERT INTO ledger(id,user_id,amount,reason,ref,day) VALUES('daily:'||NEW.user_id||':'||NEW.day,NEW.user_id,1,'Pastís del dia','daily:'||NEW.user_id||':'||NEW.day,NEW.day); END;
CREATE TABLE unlocks(user_id TEXT NOT NULL REFERENCES users(id),note_id TEXT NOT NULL REFERENCES notes(id),price INTEGER NOT NULL,day TEXT NOT NULL,PRIMARY KEY(user_id,note_id));
CREATE TRIGGER purchase_validation BEFORE INSERT ON unlocks BEGIN SELECT (CASE WHEN NEW.price!=(SELECT price FROM notes WHERE id=NEW.note_id) OR NEW.user_id=(SELECT author_id FROM notes WHERE id=NEW.note_id) OR(SELECT status FROM notes WHERE id=NEW.note_id)!='published' THEN RAISE(ABORT,'purchase_invalid') END); END;
CREATE TRIGGER purchase_transfer AFTER INSERT ON unlocks WHEN NEW.price>0 BEGIN INSERT INTO ledger(id,user_id,amount,reason,ref,day) VALUES('buy:'||NEW.user_id||':'||NEW.note_id,NEW.user_id,-NEW.price,'Compra d’apunts','buy:'||NEW.user_id||':'||NEW.note_id,NEW.day); INSERT INTO ledger(id,user_id,amount,reason,ref,day) VALUES('sell:'||NEW.user_id||':'||NEW.note_id,(SELECT author_id FROM notes WHERE id=NEW.note_id),NEW.price,'Apunts compartits','sell:'||NEW.user_id||':'||NEW.note_id,NEW.day); END;
CREATE TABLE grade_entries(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),subject_id TEXT NOT NULL REFERENCES subjects(id),term INTEGER NOT NULL CHECK(term BETWEEN 1 AND 3),category TEXT NOT NULL CHECK(category IN('exam','activity','participation')),title TEXT NOT NULL,date TEXT,grade REAL CHECK(grade IS NULL OR(grade>=0 AND grade<=10)),weight REAL NOT NULL CHECK(weight>=0 AND weight<=100),position INTEGER NOT NULL DEFAULT 0,template_id TEXT,custom INTEGER NOT NULL DEFAULT 0);
CREATE TABLE templates(id TEXT PRIMARY KEY,offering_id TEXT NOT NULL REFERENCES offerings(id),term INTEGER NOT NULL DEFAULT 1,category TEXT NOT NULL,title TEXT NOT NULL,date TEXT,weight REAL NOT NULL,position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE grade_goals(user_id TEXT NOT NULL REFERENCES users(id),subject_id TEXT NOT NULL REFERENCES subjects(id),term INTEGER NOT NULL,target REAL NOT NULL CHECK(target BETWEEN 0 AND 10),PRIMARY KEY(user_id,subject_id,term));
CREATE TABLE proposals(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Proposat' CHECK(status IN('Proposat','En estudi','Planificat','Fet')),response TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TABLE votes(user_id TEXT NOT NULL REFERENCES users(id),proposal_id TEXT NOT NULL REFERENCES proposals(id) ON DELETE CASCADE,PRIMARY KEY(user_id,proposal_id));
CREATE TABLE announcements(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,group_id TEXT REFERENCES groups(id),pinned INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TABLE banners(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,color TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),previous_id TEXT,file_id TEXT REFERENCES files(id),day TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TRIGGER banner_version BEFORE INSERT ON banners BEGIN SELECT (CASE WHEN COALESCE(NEW.previous_id,'')!=COALESCE((SELECT id FROM banners ORDER BY rowid DESC LIMIT 1),'') THEN RAISE(ABORT,'bid_changed') END); SELECT (CASE WHEN NEW.amount<COALESCE((SELECT MAX(1,CAST(ceil(amount*pow(0.9,MAX(0,CAST(julianday('now')-julianday(created_at) AS INTEGER)))) AS INTEGER))*2 FROM banners ORDER BY rowid DESC LIMIT 1),10) THEN RAISE(ABORT,'bid_low') END); END;
CREATE TRIGGER banner_debit AFTER INSERT ON banners BEGIN INSERT INTO ledger(id,user_id,amount,reason,ref,day) VALUES('banner:'||NEW.id,NEW.author_id,-NEW.amount,'Missatge de la comunitat','banner:'||NEW.id,NEW.day); END;
CREATE TABLE focus_settings(user_id TEXT PRIMARY KEY REFERENCES users(id),work INTEGER NOT NULL DEFAULT 25,rest INTEGER NOT NULL DEFAULT 5,long_rest INTEGER NOT NULL DEFAULT 15,rounds INTEGER NOT NULL DEFAULT 4);
CREATE TABLE focus_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),subject_id TEXT REFERENCES subjects(id),task TEXT NOT NULL DEFAULT '',minutes INTEGER NOT NULL,day TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE TABLE challenges(user_id TEXT NOT NULL REFERENCES users(id),day TEXT NOT NULL,answer TEXT NOT NULL,PRIMARY KEY(user_id,day));
CREATE TRIGGER challenge_credit AFTER INSERT ON challenges BEGIN INSERT INTO ledger(id,user_id,amount,reason,ref,day) VALUES('challenge:'||NEW.user_id||':'||NEW.day,NEW.user_id,1,'Repte de la pastisseria','challenge:'||NEW.user_id||':'||NEW.day,NEW.day); END;
CREATE TABLE reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),type TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%S','now')));
CREATE INDEX events_date ON events(date);
CREATE INDEX notes_subject ON notes(subject_id,status);
CREATE INDEX ledger_user ON ledger(user_id,created_at);
CREATE INDEX sessions_expiry ON sessions(expires);
CREATE INDEX grades_user ON grade_entries(user_id,term);
